/* ═══ sanitize.js ═══ */
/* ============================================================
   HTML Sanitizer (D-C7 — XSS Prevention)
   Wraps user-generated content before innerHTML injection.
   Whitelist-based: only allows safe tags/attributes.
   ============================================================ */
(function () {
  'use strict';

  var SAFE_TAGS = new Set([
    'b', 'i', 'u', 'em', 'strong', 'span', 'br', 'p', 'a',
    'code', 'pre', 'blockquote', 'mark', 'small', 'sub', 'sup',
    'ul', 'ol', 'li', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
    'table', 'thead', 'tbody', 'tr', 'th', 'td', 'img'
  ]);

  var SAFE_ATTRS = new Set([
    'href', 'target', 'rel', 'title', 'alt', 'src', 'class',
    'width', 'height', 'data-type', 'data-id', 'role',
    'aria-label', 'aria-hidden', 'tabindex', 'colspan', 'rowspan'
  ]);

  var EVENT_ATTR_REGEX = /^on[a-z]/i;

  var DANGEROUS_CSS_PROPS = [
    'position', 'z-index', 'behavior', '-moz-binding',
    'expression', 'javascript', 'vbscript', 'data:'
  ];

  var BLOCKED_PROTOCOLS = ['javascript:', 'data:', 'vbscript:', 'file:', 'blob:'];

  var ENTITY_MAP = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#x27;', '/': '&#x2F;' };
  var ENTITY_REGEX = /[&<>"'\/]/g;

  /** @param {string} str - Raw string to escape @returns {string} HTML-entity-safe string */
  function escapeHTML(str) {
    if (typeof str !== 'string') return '';
    return str.replace(ENTITY_REGEX, function (c) { return ENTITY_MAP[c]; });
  }

  function decodeHTMLEntities(str) {
    if (typeof str !== 'string') return '';
    var el = document.createElement('div');
    el.textContent = str;
    return el.textContent;
  }

  /** @param {string} url - URL to validate @returns {string} The original URL or empty string if dangerous */
  function sanitizeURL(url) {
    if (typeof url !== 'string') return '';
    var decoded = decodeHTMLEntities(url).trim();
    var trimmed = decoded.toLowerCase();
    for (var i = 0; i < BLOCKED_PROTOCOLS.length; i++) {
      if (trimmed.startsWith(BLOCKED_PROTOCOLS[i])) return '';
    }
    var stripped = trimmed.replace(/[\s\x00-\x1f]+/g, '');
    for (var j = 0; j < BLOCKED_PROTOCOLS.length; j++) {
      if (stripped.startsWith(BLOCKED_PROTOCOLS[j])) return '';
    }
    return url;
  }

  function sanitizeCSSValue(value) {
    if (typeof value !== 'string') return '';
    var lower = value.toLowerCase();
    for (var i = 0; i < DANGEROUS_CSS_PROPS.length; i++) {
      if (lower.indexOf(DANGEROUS_CSS_PROPS[i]) !== -1) return '';
    }
    if (lower.indexOf('url(') !== -1) return '';
    return value;
  }

  function sanitizeAttributes(tagName, attrStr) {
    if (!attrStr) return '';
    var result = [];
    var attrRegex = /([a-zA-Z\-]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
    var match;
    while ((match = attrRegex.exec(attrStr))) {
      var name = match[1].toLowerCase();
      var value = match[2] !== undefined ? match[2] : match[3];

      if (EVENT_ATTR_REGEX.test(name)) continue;
      if (!SAFE_ATTRS.has(name)) continue;

      if (name === 'href' || name === 'src') {
        var safeURL = sanitizeURL(value);
        if (safeURL) result.push(name + '="' + escapeHTML(safeURL) + '"');
      } else if (name === 'style') {
        var safeCSS = sanitizeCSSValue(value);
        if (safeCSS) result.push(name + '="' + escapeHTML(safeCSS) + '"');
      } else {
        result.push(name + '="' + escapeHTML(value) + '"');
      }
    }
    return result.join(' ');
  }

  /** @param {string} html - Raw HTML string @returns {string} Sanitized HTML with only safe tags/attributes */
  function sanitize(html) {
    if (typeof html !== 'string') return '';
    if (html.indexOf('<') === -1 && html.indexOf('&') === -1) return html;

    var result = '';
    var i = 0;
    var len = html.length;

    while (i < len) {
      if (html[i] === '<') {
        var isClosing = html[i + 1] === '/';
        var startIdx = isClosing ? i + 2 : i + 1;

        var tagName = '';
        var j = startIdx;
        while (j < len && /[a-zA-Z0-9\-]/.test(html[j])) {
          tagName += html[j];
          j++;
        }
        tagName = tagName.toLowerCase();

        if (tagName && SAFE_TAGS.has(tagName)) {
          var tagEnd = j;
          var inQuote = false;
          var quoteChar = '';
          while (tagEnd < len) {
            if (inQuote) {
              if (html[tagEnd] === quoteChar) inQuote = false;
            } else {
              if (html[tagEnd] === '"' || html[tagEnd] === "'") {
                inQuote = true;
                quoteChar = html[tagEnd];
              } else if (html[tagEnd] === '>') {
                break;
              }
            }
            tagEnd++;
          }

          var fullTag = html.substring(i, tagEnd + 1);
          var isSelfClosing = fullTag.endsWith('/>');
          var attrStr = html.substring(j, tagEnd).replace(/\/$/, '').trim();

          if (isClosing) {
            result += '</' + tagName + '>';
          } else {
            var safeAttrs = sanitizeAttributes(tagName, attrStr);
            result += '<' + tagName + (safeAttrs ? ' ' + safeAttrs : '') + (isSelfClosing ? ' /' : '') + '>';
          }
          i = tagEnd + 1;
        } else {
          result += escapeHTML(html[i]);
          i++;
        }
      } else {
        result += html[i];
        i++;
      }
    }

    return result;
  }

  window.NSLSanitize = { sanitize: sanitize, escapeHTML: escapeHTML, sanitizeURL: sanitizeURL };
  window.sanitizeHTML = sanitize;
  window.sanitizeContent = sanitize;
  window.escHtml = escapeHTML;

  function safeInner(el, html) {
    if (el) el.innerHTML = sanitize(html);
  }
  window.sanitizeInto = safeInner;

})();

/* ═══ clipboard-paste.js ═══ */
/* ============================================================
   Clipboard Paste Handler (D-C1)
   Handles paste of images, files, and text from clipboard on
   the main chat area — desktop & mobile.
   ============================================================ */
(function () {
  'use strict';

  const PASTE_TYPES = {
    image: ['image/png', 'image/jpeg', 'image/gif', 'image/webp'],
    video: ['video/mp4', 'video/webm'],
    audio: ['audio/mpeg', 'audio/ogg', 'audio/wav'],
    file: [
      'application/pdf', 'application/zip', 'application/x-rar-compressed',
      'text/plain', 'text/csv', 'application/json'
    ]
  };

  const MAX_PASTE_SIZE = 25 * 1024 * 1024; // 25 MB
  const MAX_PASTE_FILES = 10;

  function classifyMIME(type) {
    for (const [cat, mimes] of Object.entries(PASTE_TYPES)) {
      if (mimes.includes(type)) return cat;
    }
    return 'file';
  }

  function formatBytes(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
  }

  function showPasteError(msg) {
    if (typeof showToast === 'function') {
      showToast(msg, 'error');
    } else {
      console.warn('[ClipboardPaste]', msg);
    }
  }

  function dispatchFilesToComposer(files) {
    if (!files || files.length === 0) return;

    if (files.length > MAX_PASTE_FILES) {
      showPasteError(`Maximum ${MAX_PASTE_FILES} files at once.`);
      return;
    }

    const oversized = Array.from(files).find(f => f.size > MAX_PASTE_SIZE);
    if (oversized) {
      showPasteError(`File "${oversized.name}" exceeds ${formatBytes(MAX_PASTE_SIZE)} limit.`);
      return;
    }

    // Create a synthetic DataTransfer so existing drop handlers can consume the files
    const dt = new DataTransfer();
    Array.from(files).forEach(f => dt.items.add(f));

    const dropTarget = document.querySelector('#msg-input') ||
                       document.querySelector('#messages-wrap') ||
                       document.querySelector('#chat-area');

    if (dropTarget) {
      const dropEvent = new DragEvent('drop', {
        bubbles: true,
        cancelable: true,
        dataTransfer: dt
      });
      dropTarget.dispatchEvent(dropEvent);
    }

    // Fallback: if no drop handler processed it, try the file input
    if (dt.files.length > 0) {
      const fileInput = document.querySelector('#file-input, input[type="file"]');
      if (fileInput) {
        fileInput.files = dt.files;
        fileInput.dispatchEvent(new Event('change', { bubbles: true }));
      }
    }
  }

  function handlePasteEvent(e) {
    const clipData = e.clipboardData || window.clipboardData;
    if (!clipData) return;

    const items = clipData.items;
    if (!items || items.length === 0) return;

    const files = [];
    let hasImage = false;

    for (let i = 0; i < items.length; i++) {
      const item = items[i];
      if (item.kind === 'file') {
        const file = item.getAsFile();
        if (file) {
          files.push(file);
          if (classifyMIME(file.type) === 'image') hasImage = true;
        }
      }
    }

    // If files are pasted, prevent default and dispatch to composer
    if (files.length > 0) {
      e.preventDefault();
      e.stopPropagation();
      dispatchFilesToComposer(files);
      return;
    }

    // For text paste — let it flow normally into the input
    // (no interception needed, default behavior handles it)
  }

  function init() {
    // Listen on chat area for paste events
    const chatArea = document.querySelector('#chat-area') ||
                     document.querySelector('#messages-wrap') ||
                     document.body;

    if (chatArea) {
      chatArea.addEventListener('paste', handlePasteEvent, { capture: true });
    }

    // Also listen on the message input specifically
    const msgInput = document.querySelector('#msg-input');
    if (msgInput) {
      msgInput.addEventListener('paste', handlePasteEvent, { capture: true });
    }
  }

  // Init when DOM is ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* ═══ desktop-fullscreen.js ═══ */
/* ============================================================
   Desktop Fullscreen & PiP (D-C2 / D-C3) v1.1
   Adds actual fullscreen toggle and picture-in-picture support
   for media viewer, video calls, and image viewer.
   ── v1.1: MutationBus + named handlers + destroy()
   ============================================================ */
(function () {
  'use strict';

  var _cleanupFns = [];
  var _observers = [];
  function _trackCleanup(fn) { _cleanupFns.push(fn); }

  /* --- Fullscreen (D-C2) --- */

  function isFullscreenSupported() {
    return !!(
      document.fullscreenEnabled ||
      document.webkitFullscreenEnabled ||
      document.mozFullScreenEnabled ||
      document.msFullscreenEnabled
    );
  }

  function requestFullscreen(el) {
    if (el.requestFullscreen) return el.requestFullscreen();
    if (el.webkitRequestFullscreen) return el.webkitRequestFullscreen();
    if (el.mozRequestFullScreen) return el.mozRequestFullScreen();
    if (el.msRequestFullscreen) return el.msRequestFullscreen();
    return Promise.reject(new Error('Fullscreen not supported'));
  }

  function exitFullscreen() {
    if (document.exitFullscreen) return document.exitFullscreen();
    if (document.webkitExitFullscreen) return document.webkitExitFullscreen();
    if (document.mozCancelFullScreen) return document.mozCancelFullScreen();
    if (document.msExitFullscreen) return document.msExitFullscreen();
    return Promise.resolve();
  }

  function isCurrentlyFullscreen() {
    return !!(
      document.fullscreenElement ||
      document.webkitFullscreenElement ||
      document.mozFullScreenElement ||
      document.msFullscreenElement
    );
  }

  function toggleFullscreen(el) {
    if (!isFullscreenSupported()) {
      if (typeof showToast === 'function') showToast('Fullscreen not supported in this browser', 'error');
      return;
    }
    if (isCurrentlyFullscreen()) {
      exitFullscreen();
    } else {
      const target = el || document.querySelector('#media-viewer') ||
                     document.querySelector('#video-player-wrap') ||
                     document.querySelector('#call-screen') ||
                     document.querySelector('#chat-area') ||
                     document.documentElement;
      requestFullscreen(target).catch(() => {
        if (typeof showToast === 'function') showToast('Could not enter fullscreen', 'error');
      });
    }
  }

  /* --- Picture-in-Picture (D-C3) --- */

  function isPiPSupported() {
    return typeof document.pictureInPictureEnabled !== 'undefined' && document.pictureInPictureEnabled;
  }

  function requestPiP(videoEl) {
    if (!isPiPSupported()) {
      if (typeof showToast === 'function') showToast('Picture-in-Picture not supported', 'error');
      return Promise.reject(new Error('PiP not supported'));
    }
    if (!videoEl || videoEl.tagName !== 'VIDEO') {
      if (typeof showToast === 'function') showToast('No video element found', 'error');
      return Promise.reject(new Error('No video element'));
    }
    return videoEl.requestPictureInPicture().catch(err => {
      if (typeof showToast === 'function') showToast('Could not enter PiP mode', 'error');
      return Promise.reject(err);
    });
  }

  function exitPiP() {
    if (document.pictureInPictureElement) {
      return document.pictureInPictureElement.exitPictureInPicture();
    }
    return Promise.resolve();
  }

  /* --- Hook into UI elements --- */

  function addFullscreenButtons() {
    const mediaViewer = document.querySelector('#media-viewer');
    if (mediaViewer && !mediaViewer.querySelector('.fs-toggle-btn')) {
      const btn = document.createElement('button');
      btn.className = 'fs-toggle-btn';
      btn.setAttribute('aria-label', 'Toggle fullscreen');
      btn.setAttribute('title', 'Fullscreen (F11)');
      btn.innerHTML = '⛶';
      btn.style.cssText = 'position:absolute;top:12px;right:48px;z-index:10010;background:rgba(0,0,0,0.6);color:#fff;border:none;border-radius:50%;width:36px;height:36px;font-size:18px;cursor:pointer;display:flex;align-items:center;justify-content:center;';
      function _onFSClick() { toggleFullscreen(mediaViewer); }
      btn.addEventListener('click', _onFSClick);
      _trackCleanup(function () { btn.removeEventListener('click', _onFSClick); });
      mediaViewer.appendChild(btn);
    }

    const videoPlayer = document.querySelector('#video-player-wrap, #media-viewer video');
    if (videoPlayer && isPiPSupported()) {
      const videoEl = videoPlayer.tagName === 'VIDEO' ? videoPlayer : videoPlayer.querySelector('video');
      if (videoEl && !videoPlayer.querySelector('.pip-toggle-btn')) {
        const btn = document.createElement('button');
        btn.className = 'pip-toggle-btn';
        btn.setAttribute('aria-label', 'Picture in Picture');
        btn.setAttribute('title', 'Picture in Picture');
        btn.innerHTML = '⧉';
        btn.style.cssText = 'position:absolute;bottom:48px;right:12px;z-index:10010;background:rgba(0,0,0,0.6);color:#fff;border:none;border-radius:50%;width:36px;height:36px;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;';
        function _onPiPClick() {
          if (document.pictureInPictureElement) exitPiP();
          else requestPiP(videoEl);
        }
        btn.addEventListener('click', _onPiPClick);
        _trackCleanup(function () { btn.removeEventListener('click', _onPiPClick); });
        videoPlayer.appendChild(btn);
      }
    }
  }

  /* --- Fullscreen change indicator for body class --- */

  function watchFullscreenChange() {
    function onFSChange() {
      document.body.classList.toggle('is-fullscreen', isCurrentlyFullscreen());
    }
    document.addEventListener('fullscreenchange', onFSChange);
    document.addEventListener('webkitfullscreenchange', onFSChange);
    document.addEventListener('mozfullscreenchange', onFSChange);
    document.addEventListener('MSFullscreenChange', onFSChange);
    _trackCleanup(function () {
      document.removeEventListener('fullscreenchange', onFSChange);
      document.removeEventListener('webkitfullscreenchange', onFSChange);
      document.removeEventListener('mozfullscreenchange', onFSChange);
      document.removeEventListener('MSFullscreenChange', onFSChange);
    });
  }

  /* --- Init --- */

  function init() {
    addFullscreenButtons();
    watchFullscreenChange();

    window.NSLDesktop = window.NSLDesktop || {};
    window.NSLDesktop.toggleFullscreen = toggleFullscreen;
    window.NSLDesktop.requestPiP = requestPiP;
    window.NSLDesktop.exitPiP = exitPiP;
    window.NSLDesktop.isFullscreenSupported = isFullscreenSupported;
    window.NSLDesktop.isPiPSupported = isPiPSupported;

    if (window.MutationBus) {
      MutationBus.onBodyChildList('df:media-btns', function () {
        requestAnimationFrame(addFullscreenButtons);
      });
    } else if (typeof MutationObserver !== 'undefined') {
      var obs = new MutationObserver(function () {
        requestAnimationFrame(addFullscreenButtons);
      });
      obs.observe(document.body, { childList: true, subtree: true });
      _observers.push(obs);
    }
  }

  /* --- destroy --- */
  function destroy() {
    if (window.MutationBus) MutationBus.off('df:media-btns');
    _observers.forEach(function (o) { try { o.disconnect(); } catch (e) {} });
    _observers = [];
    _cleanupFns.forEach(function (fn) { try { fn(); } catch (e) {} });
    _cleanupFns = [];
    document.body.classList.remove('is-fullscreen');
  }

  window.NSLDesktop = window.NSLDesktop || {};
  window.NSLDesktop.destroy = destroy;

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* ═══ desktop-context-menu.js ═══ */
/* ============================================================
   Desktop Context Menu (D-H14 / D-L11)
   Right-click context menu for messages, chat list, and media.
   ============================================================ */
(function () {
  'use strict';

  let _menu = null;
  let _visible = false;

  function createMenu() {
    if (_menu) return _menu;
    _menu = document.createElement('div');
    _menu.id = 'desktop-context-menu';
    _menu.setAttribute('role', 'menu');
    _menu.setAttribute('aria-label', 'Context menu');
    _menu.style.display = 'none';
    document.body.appendChild(_menu);
    // Close on click outside
    document.addEventListener('click', () => hide());
    document.addEventListener('contextmenu', (e) => {
      // Only hide if clicking outside the menu
      if (_menu && !_menu.contains(e.target)) hide();
    });
    return _menu;
  }

  function show(x, y, items) {
    const menu = createMenu();
    menu.innerHTML = '';
    for (const item of items) {
      if (item.separator) {
        const sep = document.createElement('div');
        sep.className = 'ctx-separator';
        menu.appendChild(sep);
        continue;
      }
      const btn = document.createElement('button');
      btn.setAttribute('role', 'menuitem');
      btn.innerHTML = `<span>${item.icon || ''}</span><span>${item.label}</span>`;
      if (item.shortcut) {
        btn.innerHTML += `<span class="ctx-shortcut">${item.shortcut}</span>`;
      }
      if (item.danger) btn.classList.add('danger');
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        hide();
        if (item.action) item.action();
      });
      menu.appendChild(btn);
    }
    // Position menu
    menu.style.display = 'block';
    _visible = true;
    const rect = menu.getBoundingClientRect();
    const vw = window.innerWidth;
    const vh = window.innerHeight;
    let posX = x;
    let posY = y;
    if (x + rect.width > vw) posX = vw - rect.width - 8;
    if (y + rect.height > vh) posY = vh - rect.height - 8;
    if (posX < 0) posX = 8;
    if (posY < 0) posY = 8;
    menu.style.left = posX + 'px';
    menu.style.top = posY + 'px';
    menu.classList.add('visible');
    // Focus first item
    const firstBtn = menu.querySelector('button');
    if (firstBtn) firstBtn.focus();
  }

  function hide() {
    if (_menu) {
      _menu.classList.remove('visible');
      _menu.style.display = 'none';
      _visible = false;
    }
  }

  function isVisible() { return _visible; }

  /* --- Message context menu --- */
  function showMsgContextMenu(e, msgEl) {
    e.preventDefault();
    e.stopPropagation();
    const msgId = msgEl?.dataset?.msgId;
    const isMyMsg = msgEl?.classList?.contains('my-message');
    const items = [
      { icon: '↩', label: 'Reply', shortcut: '', action: () => { if (typeof replyToMessage === 'function') replyToMessage(msgId); } },
      { icon: '⟳', label: 'Forward', action: () => { if (typeof forwardMessage === 'function') forwardMessage(msgId); } },
      { icon: '📋', label: 'Copy', shortcut: 'Ctrl+C', action: () => {
        const text = msgEl?.querySelector('.msg-text, .message-bubble')?.textContent;
        if (text) navigator.clipboard?.writeText(text);
      }},
      { icon: '📌', label: 'Star', action: () => { if (typeof starMessage === 'function') starMessage(msgId); } },
      { separator: true },
      { icon: 'ℹ', label: 'Info', action: () => { if (typeof showMessageInfo === 'function') showMessageInfo(msgId); } },
      ...(isMyMsg ? [
        { separator: true },
        { icon: '✏', label: 'Edit', shortcut: 'F2', action: () => { if (typeof editMessage === 'function') editMessage(msgId); } },
        { icon: '🗑', label: 'Delete', shortcut: 'Del', danger: true, action: () => { if (typeof deleteMessage === 'function') deleteMessage(msgId); } },
      ] : [
        { separator: true },
        { icon: '🗑', label: 'Delete', shortcut: 'Del', danger: true, action: () => { if (typeof deleteMessage === 'function') deleteMessage(msgId); } },
      ]),
    ];
    show(e.clientX, e.clientY, items);
  }

  /* --- Chat list context menu --- */
  function showChatContextMenu(e, chatEl) {
    e.preventDefault();
    e.stopPropagation();
    const chatId = chatEl?.dataset?.chatId || chatEl?.id;
    const isPinned = chatEl?.classList?.contains('pinned');
    const isMuted = chatEl?.classList?.contains('muted');
    const items = [
      { icon: '📌', label: isPinned ? 'Unpin' : 'Pin', action: () => { if (typeof togglePinChat === 'function') togglePinChat(chatId); } },
      { icon: '🔇', label: isMuted ? 'Unmute' : 'Mute', action: () => { if (isMuted) { if (typeof toggleMuteChat === 'function') toggleMuteChat(chatId); } else { if (typeof showMuteChatOptions === 'function') showMuteChatOptions(chatId); } } },
      { icon: '📁', label: 'Archive', shortcut: 'Ctrl+Shift+A', action: () => { if (typeof archiveChat === 'function') archiveChat(chatId); } },
      { separator: true },
      { icon: '👤', label: 'View contact', action: () => { if (typeof viewContact === 'function') viewContact(chatId); } },
      { icon: '🔍', label: 'Search', shortcut: 'Ctrl+Shift+F', action: () => { if (typeof openChatSearch === 'function') openChatSearch(); } },
      { separator: true },
      { icon: '🗑', label: 'Delete chat', shortcut: 'Ctrl+Shift+D', danger: true, action: () => { if (typeof deleteChat === 'function') deleteChat(chatId); } },
    ];
    show(e.clientX, e.clientY, items);
  }

  /* --- Media context menu --- */
  function showMediaContextMenu(e, mediaEl) {
    e.preventDefault();
    e.stopPropagation();
    const src = mediaEl?.src || mediaEl?.querySelector('img, video')?.src;
    const items = [
      { icon: '🔍', label: 'Open in new tab', action: () => { if (src) window.open(src, '_blank'); } },
      { icon: '📋', label: 'Copy image URL', action: () => { if (src) navigator.clipboard?.writeText(src); } },
      { icon: '💾', label: 'Save as…', action: () => { if (src) { const a = document.createElement('a'); a.href = src; a.download = ''; a.click(); } } },
      { separator: true },
      { icon: '⛶', label: 'Fullscreen', shortcut: 'F11', action: () => { if (window.NSLDesktop?.toggleFullscreen) window.NSLDesktop.toggleFullscreen(); } },
    ];
    show(e.clientX, e.clientY, items);
  }

  /* --- Init: attach event listeners --- */
  function init() {
    // Message right-click
    document.addEventListener('contextmenu', (e) => {
      const msgEl = e.target.closest('.message[data-msg-id]');
      if (msgEl) { showMsgContextMenu(e, msgEl); return; }
      const chatEl = e.target.closest('.chat-list-item');
      if (chatEl) { showChatContextMenu(e, chatEl); return; }
      const mediaEl = e.target.closest('#media-viewer img, #media-viewer video, .bubble-media img, .bubble-media video');
      if (mediaEl) { showMediaContextMenu(e, mediaEl); return; }
    });
    // Keyboard: Escape hides context menu
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && _visible) hide();
    });
  }

  window.NSLContextMenu = { show, hide, isVisible, showMsgContextMenu, showChatContextMenu, showMediaContextMenu };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();

/* ═══ window-title.js ═══ */
/* ============================================================
   Window Title Manager (D-H13 / D-L4)
   Updates document.title with unread count and current chat.
   ============================================================ */
(function () {
  'use strict';

  const BASE_TITLE = 'NSL Chat';
  let _unreadCount = 0;
  let _currentChat = null;
  let _typingUsers = [];

  function formatTitle() {
    let title = BASE_TITLE;

    if (_currentChat) {
      const chatName = _currentChat.name || _currentChat.groupName || 'Chat';
      title = chatName + ' — ' + BASE_TITLE;
    }

    if (_unreadCount > 0) {
      const badge = _unreadCount > 99 ? '99+' : String(_unreadCount);
      title = `(${badge}) ${title}`;
    }

    return title;
  }

  function updateTitle() {
    document.title = formatTitle();
    updateFaviconBadge();
  }

  function setUnreadCount(count) {
    _unreadCount = typeof count === 'number' ? count : 0;
    updateTitle();
  }

  function incrementUnread() {
    _unreadCount++;
    updateTitle();
  }

  function clearUnread() {
    _unreadCount = 0;
    updateTitle();
  }

  function setCurrentChat(chatInfo) {
    _currentChat = chatInfo;
    updateTitle();
  }

  function setTyping(userName) {
    if (userName && !_typingUsers.includes(userName)) {
      _typingUsers.push(userName);
      document.title = `${userName} is typing… — ${BASE_TITLE}`;
    }
  }

  function clearTyping(userName) {
    _typingUsers = _typingUsers.filter(u => u !== userName);
    if (_typingUsers.length === 0) {
      updateTitle();
    } else {
      document.title = `${_typingUsers[0]} is typing… — ${BASE_TITLE}`;
    }
  }

  /* --- Favicon badge (D-L4) --- */
  let _originalFaviconHref = null;

  function updateFaviconBadge() {
    const link = document.querySelector('link[rel="icon"], link[rel="shortcut icon"]');
    if (!link) return;

    if (!_originalFaviconHref) {
      _originalFaviconHref = link.href;
    }

    // Remove existing dynamic favicon
    const existing = document.querySelector('link[rel="dynamic-favicon"]');
    if (existing) existing.remove();

    if (_unreadCount === 0) {
      link.href = _originalFaviconHref;
      return;
    }

    const canvas = document.createElement('canvas');
    canvas.width = 64;
    canvas.height = 64;
    const ctx = canvas.getContext('2d');

    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = function () {
      ctx.drawImage(img, 0, 0, 64, 64);

      // Draw red badge circle
      ctx.beginPath();
      ctx.arc(48, 16, 14, 0, Math.PI * 2);
      ctx.fillStyle = '#FF3B30';
      ctx.fill();

      // Draw count text
      const badge = _unreadCount > 99 ? '99+' : String(_unreadCount);
      ctx.fillStyle = '#FFFFFF';
      ctx.font = 'bold 16px -apple-system, BlinkMacSystemFont, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(badge, 48, 16);

      const dynLink = document.createElement('link');
      dynLink.rel = 'dynamic-favicon';
      dynLink.type = 'image/png';
      dynLink.href = canvas.toDataURL('image/png');
      document.head.appendChild(dynLink);
    };
    img.onerror = function () {
      // Fallback: just set a simple badge
    };
    img.src = _originalFaviconHref;
  }

  /* --- Visibility change: flash title on message --- */
  let _flashInterval = null;
  const FLASH_MESSAGES = ['💬 New message', '📩 New message', '💬 New', '📩 New'];

  function flashTitle(enable) {
    if (_flashInterval) {
      clearInterval(_flashInterval);
      _flashInterval = null;
    }
    if (!enable) {
      updateTitle();
      return;
    }
    let idx = 0;
    _flashInterval = setInterval(() => {
      document.title = FLASH_MESSAGES[idx % FLASH_MESSAGES.length];
      idx++;
    }, 1500);
  }

  /* --- Expose API --- */
  window.NSLWindowTitle = {
    setUnreadCount,
    incrementUnread,
    clearUnread,
    setCurrentChat,
    setTyping,
    clearTyping,
    flashTitle,
    updateTitle
  };

  // Auto-hook into incoming messages if config.js dispatches events
  document.addEventListener('nsl:new-message', () => {
    if (document.hidden) {
      incrementUnread();
      flashTitle(true);
    }
  });

  document.addEventListener('nsl:chat-opened', (e) => {
    const chat = e.detail || {};
    setCurrentChat(chat);
    if (document.hasFocus()) {
      clearUnread();
      flashTitle(false);
    }
  });

  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) {
      flashTitle(false);
    }
  });

})();

/* ═══ whatsapp-share.js ═══ */
// ========================================================
// whatsapp-share.js  v1
// Adds two options to every message long-press menu:
//   1. "Share to WhatsApp"  — opens wa.me link with message text
//   2. "Save to My Notes"   — forwards message to Saved Messages
//
// Works in browser AND Android Capacitor app.
// Place in works/chat/ and add before </body> in index.html:
//   <script src="whatsapp-share.js" defer></script>
// ========================================================

(function () {
  'use strict';

  // ── Wait until the core app globals are ready ───────────────
  let _tries = 0;
  function waitForApp(cb) {
    if (typeof showContextMenu === 'function' && typeof db !== 'undefined') {
      cb();
    } else if (_tries++ < 120) {
      setTimeout(() => waitForApp(cb), 250);
    } else {
      console.warn('[wa-share] Core app not found after 30s, giving up.');
    }
  }

  // ── Share to WhatsApp ────────────────────────────────────────
  function shareToWhatsApp(messageData) {
    const text = (messageData.text || '').trim();
    const caption = messageData.attachment?.caption || '';
    const combined = [text, caption].filter(Boolean).join('\n');

    if (!combined) {
      if (typeof showToast === 'function') showToast('No text to share', 'error');
      return;
    }

    const url = 'https://wa.me/?text=' + encodeURIComponent(combined);

    // On Android Capacitor: use native browser plugin if available, else window.open
    const BrowserPlugin = window.Capacitor?.Plugins?.Browser;
    if (BrowserPlugin?.open) {
      BrowserPlugin.open({ url });
    } else {
      window.open(url, '_blank', 'noopener,noreferrer');
    }
  }

  // ── Save to My Notes (Saved Messages) ───────────────────────
  async function saveToMyNotes(messageData) {
    if (typeof currentUser === 'undefined' || !currentUser) {
      if (typeof showToast === 'function') showToast('Please sign in first', 'error');
      return;
    }

    const chatId = typeof getSavedMessagesChatId === 'function'
      ? getSavedMessagesChatId()
      : `saved_${currentUser.uid}`;

    if (!chatId) return;

    // Ensure the saved-messages Firestore doc exists
    try {
      const chatRef = db.collection('directChats').doc(chatId);
      const snap = await chatRef.get();
      if (!snap.exists) {
        await chatRef.set({
          participants: [currentUser.uid],
          status: 'active',
          saved: true,
          createdAt: firebase.firestore.FieldValue.serverTimestamp(),
        });
      }
    } catch (e) {
      console.warn('[wa-share] Could not ensure saved-messages doc:', e);
    }

    const senderName = messageData.senderName || currentUser.displayName || 'Me';
    const originalTime = messageData.timestamp
      ? (messageData.timestamp.toDate
          ? messageData.timestamp.toDate().toLocaleString()
          : new Date(messageData.timestamp).toLocaleString())
      : '';
    const header = originalTime
      ? `Forwarded from ${senderName} (${originalTime}):\n`
      : `Forwarded from ${senderName}:\n`;
    const body = (messageData.text || '').trim();
    const textToSave = body ? header + body : '';

    const msgDoc = {
      directId: chatId,
      senderId: currentUser.uid,
      senderName: currentUser.displayName || currentUser.email || 'Me',
      receiverId: currentUser.uid,
      timestamp: firebase.firestore.FieldValue.serverTimestamp(),
      readBy: { [currentUser.uid]: firebase.firestore.FieldValue.serverTimestamp() },
      ...(textToSave ? { text: textToSave } : {}),
    };

    // Forward attachment if present
    if (messageData.attachment) {
      msgDoc.attachment = { ...messageData.attachment };
      if (!textToSave) msgDoc.text = header.trim();
    }

    try {
      await db.collection('messages').add(msgDoc);
      if (typeof showToast === 'function') showToast('Saved to My Notes ⭐', 'success');
    } catch (e) {
      console.error('[wa-share] Save to notes failed:', e);
      if (typeof showToast === 'function') showToast('Could not save to notes', 'error');
    }
  }

  // ── Inject extra buttons via DOM MutationObserver ───────────
  // We watch for .message-context-menu being added, then append our buttons.
  // This is non-invasive — no patching of existing functions needed.
  function injectMenuItems(menu, messageData) {
    // Avoid double-injection
    if (menu.dataset.waShareInjected) return;
    menu.dataset.waShareInjected = 'true';

    const text = (messageData?.text || '').trim();
    const hasText = Boolean(text || messageData?.attachment?.caption);

    // "Share to WhatsApp" — only when there is text/caption to share
    if (hasText) {
      const waBtn = document.createElement('button');
      waBtn.type = 'button';
      waBtn.className = 'context-menu-item wa-share-btn';
      waBtn.innerHTML = '<span class="wa-share-icon">📤</span> Share to WhatsApp';
      waBtn.addEventListener('click', () => {
        if (typeof removeMessageContextMenu === 'function') removeMessageContextMenu();
        shareToWhatsApp(messageData);
      });
      menu.appendChild(waBtn);
    }

    // "Save to My Notes" — always available (forwards text + attachments)
    const notesBtn = document.createElement('button');
    notesBtn.type = 'button';
    notesBtn.className = 'context-menu-item wa-notes-btn';
    notesBtn.innerHTML = '<span class="wa-notes-icon">⭐</span> Save to My Notes';
    notesBtn.addEventListener('click', () => {
      if (typeof removeMessageContextMenu === 'function') removeMessageContextMenu();
      saveToMyNotes(messageData);
    });
    menu.appendChild(notesBtn);
  }

  // ── MutationObserver: watch for context menu appearing ──────
  function observeContextMenus() {
    const observer = new MutationObserver((mutations) => {
      for (const m of mutations) {
        for (const node of m.addedNodes) {
          if (node.nodeType !== 1) continue;
          if (!node.classList.contains('message-context-menu')) continue;
          // Retrieve message data from the currently selected message element
          // The app stores messageId in the long-press handler; we read dataset
          const msgId = node.dataset?.messageId || '';
          // Read messageData from the closest .message element that has focus
          let messageData = null;
          try {
            // Try global map used by the app
            if (typeof window._lastContextMenuMessageData !== 'undefined') {
              messageData = window._lastContextMenuMessageData;
            }
          } catch (_) {}
          injectMenuItems(node, messageData || {});
        }
      }
    });
    observer.observe(document.body, { childList: true, subtree: false });
  }

  // ── Patch showContextMenu to capture messageData ─────────────
  // We wrap the existing function once to record the messageData
  // so the MutationObserver can access it.
  function patchShowContextMenu() {
    const original = window.showContextMenu;
    if (!original || typeof original !== 'function') return;
    window.showContextMenu = function (x, y, messageId, messageData, isMyMessage) {
      window._lastContextMenuMessageData = messageData || null;
      return original.call(this, x, y, messageId, messageData, isMyMessage);
    };
  }

  // ── CSS injection ────────────────────────────────────────────
  function injectStyles() {
    if (document.getElementById('_wa_share_styles')) return;
    const s = document.createElement('style');
    s.id = '_wa_share_styles';
    s.textContent = `
      .wa-share-btn .wa-share-icon,
      .wa-notes-btn .wa-notes-icon {
        margin-right: 6px;
        font-size: 15px;
      }
      .wa-share-btn:hover {
        background: #e7f8ee !important;
        color: #128c7e !important;
      }
      body.dark .wa-share-btn:hover {
        background: #0b3d35 !important;
        color: #25d366 !important;
      }
      .wa-notes-btn:hover {
        background: #fffbe6 !important;
        color: #b8860b !important;
      }
      body.dark .wa-notes-btn:hover {
        background: #3a3000 !important;
        color: #ffd700 !important;
      }
    `;
    document.head.appendChild(s);
  }

  // ── Boot ────────────────────────────────────────────────────
  function boot() {
    injectStyles();
    patchShowContextMenu();
    observeContextMenus();
    if (window.__DEBUG__) console.log('[wa-share] Share to WhatsApp + Save to My Notes ready');
  }

  waitForApp(boot);
})();

/* ═══ swipe-nav.js ═══ */
// swipe-nav.js  v1
// Swipe-right anywhere in the chat panel to go back to the chat list.
// Works on: iOS Safari, Android Chrome/Firefox/Samsung Browser,
//           installed PWA (standalone), touch laptops, stylus/hybrid devices.
// Does NOT intercept: vertical scrolls, horizontal code-block scrolls,
//                     taps on inputs/buttons, or swipes while a modal is open.

(function () {
  'use strict';

  var TRIGGER_PX  = 68;   // px dragged rightward to trigger close
  var TRIGGER_VEL = 0.40; // px/ms  — fast flick triggers even under TRIGGER_PX

  var sx = 0, sy = 0, lx = 0, lt = 0;
  var active = false, axisLocked = false, isHoriz = false;

  /* ── environment checks ────────────────────────────────────────────── */

  function isTouchEnv() {
    /* C5: Only activate on phones (<768px) or PWA — not tablets with mouse/trackpad */
    if (window.matchMedia('(display-mode: standalone)').matches) return true;
    if (typeof navigator.standalone === 'boolean' && navigator.standalone) return true;
    /* On tablets, only enable if pure touch (no fine pointer = no mouse/trackpad) */
    if (window.matchMedia('(max-width: 767px)').matches) return true;
    if (window.matchMedia('(pointer: coarse) and (hover: none)').matches && window.innerWidth < 1024) return true;
    return false;
  }

  function isChatOpen() {
    var el = document.getElementById('chat-area');
    return el && !el.classList.contains('hidden') && !el.classList.contains('hidden-mobile');
  }

  function isModalOpen() {
    var m = document.querySelector('#callModal');
    if (m && (m.style.display === 'flex' || m.style.display === 'block')) return true;
    if (document.querySelector('.modal-overlay:not([style*="display: none"])')) return true;
    return false;
  }

  /* Walk up the DOM: if any ancestor is horizontally scrollable with overflow
     content, let the native scroll handle it instead of our swipe. */
  function hasScrollableParent(el) {
    var node = el;
    while (node && node !== document.body) {
      var ox = window.getComputedStyle(node).overflowX;
      if ((ox === 'auto' || ox === 'scroll') && node.scrollWidth > node.clientWidth + 4) {
        return true;
      }
      node = node.parentElement;
    }
    return false;
  }

  function isBlockedTarget(el) {
    if (!el) return false;
    var tag = (el.tagName || '').toUpperCase();
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || tag === 'BUTTON') return true;
    if (el.isContentEditable) return true;
    if (el.closest && el.closest('#messageInput, .emoji-picker, .modal, .modal-content, #callModal')) return true;
    return hasScrollableParent(el);
  }

  /* ── DOM refs ──────────────────────────────────────────────────────── */

  function chatContainer() { return document.getElementById('chat-area'); }
  function chatMainEl()    { return document.getElementById('messages-wrap'); }

  /* ── drag visual state ─────────────────────────────────────────────── */

  function beginDrag() {
    var c = chatContainer();
    if (c) c.classList.add('swipe-peeking');
  }

  function applyDrag(dx) {
    var el = chatMainEl();
    if (!el) return;
    var clamped = Math.max(0, Math.min(dx, window.innerWidth * 0.92));
    el.style.setProperty('--swipe-dx', clamped + 'px');
    el.classList.add('swipe-dragging');
  }

  function clearDrag(trigger) {
    var c  = chatContainer();
    var el = chatMainEl();
    if (c)  c.classList.remove('swipe-peeking');
    if (el) {
      el.classList.remove('swipe-dragging');
      el.style.removeProperty('--swipe-dx');
    }
    if (trigger && typeof window.closeMobileChatPanel === 'function') {
      window.closeMobileChatPanel();
    }
  }

  /* ── core gesture logic ────────────────────────────────────────────── */

  function gestureStart(cx, cy, target) {
    if (!isTouchEnv() || !isChatOpen()) return;
    if (isBlockedTarget(target) || isModalOpen()) return;
    sx = lx = cx; sy = cy; lt = Date.now();
    active = true; axisLocked = false; isHoriz = false;
  }

  function gestureMove(cx, cy, preventDefaultFn) {
    if (!active) return;
    var dx = cx - sx, dy = cy - sy;

    /* Determine axis on first few pixels */
    if (!axisLocked && (Math.abs(dx) > 6 || Math.abs(dy) > 6)) {
      axisLocked = true;
      isHoriz    = Math.abs(dx) > Math.abs(dy) && dx > 0;
      if (!isHoriz) { active = false; return; }
      beginDrag();
    }
    if (!isHoriz) return;
    if (dx < 0) { active = false; clearDrag(false); return; }

    /* Suppress native scroll / pan while we own this gesture */
    if (preventDefaultFn) preventDefaultFn();
    lx = cx; lt = Date.now();
    applyDrag(dx);
  }

  function gestureEnd(cx) {
    if (!active || !isHoriz) { active = false; clearDrag(false); return; }
    active = false;
    var dx  = cx - sx;
    var dt  = Date.now() - lt;
    var vel = dt > 0 ? (cx - lx) / dt : 0;
    clearDrag(dx >= TRIGGER_PX || vel >= TRIGGER_VEL);
  }

  function gestureCancel() { active = false; isHoriz = false; clearDrag(false); }

  /* ── Touch Events (all mobile browsers) ───────────────────────────── */

  function onTouchStart(e) {
    var t = e.touches[0];
    gestureStart(t.clientX, t.clientY, e.target);
  }
  function onTouchMove(e) {
    var t = e.touches[0];
    gestureMove(t.clientX, t.clientY, e.cancelable ? function () { e.preventDefault(); } : null);
  }
  function onTouchEnd(e) {
    var t = e.changedTouches[0];
    gestureEnd(t.clientX);
  }

  /* ── Pointer Events (touch laptops, stylus, pen, hybrid devices) ──── */

  var ptrIds = {};

  function onPointerDown(e) {
    if (e.pointerType === 'mouse') return;   /* skip desktop mouse */
    ptrIds[e.pointerId] = true;
    gestureStart(e.clientX, e.clientY, e.target);
  }
  function onPointerMove(e) {
    if (!ptrIds[e.pointerId]) return;
    gestureMove(e.clientX, e.clientY, e.cancelable ? function () { e.preventDefault(); } : null);
  }
  function onPointerUp(e) {
    if (!ptrIds[e.pointerId]) return;
    delete ptrIds[e.pointerId];
    gestureEnd(e.clientX);
  }
  function onPointerCancel(e) {
    delete ptrIds[e.pointerId];
    gestureCancel();
  }

  /* ── attach listeners ──────────────────────────────────────────────── */

  function attach() {
    var root = document.documentElement;

    root.addEventListener('touchstart',  onTouchStart, { passive: true,  capture: false });
    root.addEventListener('touchmove',   onTouchMove,  { passive: false, capture: false });
    root.addEventListener('touchend',    onTouchEnd,   { passive: true,  capture: false });
    root.addEventListener('touchcancel', gestureCancel,{ passive: true,  capture: false });

    if (window.PointerEvent) {
      root.addEventListener('pointerdown',   onPointerDown,   { passive: true  });
      root.addEventListener('pointermove',   onPointerMove,   { passive: false });
      root.addEventListener('pointerup',     onPointerUp,     { passive: true  });
      root.addEventListener('pointercancel', onPointerCancel, { passive: true  });
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', attach);
  } else {
    attach();
  }

  /* ── Close mobile chat panel (called by swipe gesture) ─────────── */
  window.closeMobileChatPanel = function() {
    var chatArea = document.getElementById('chat-area');
    var sidebar = document.getElementById('chat-list-sidebar');
    var chatHeader = document.getElementById('chat-header');
    if (chatArea) {
      chatArea.classList.remove('visible-mobile');
      chatArea.classList.add('hidden-mobile');
    }
    if (sidebar) sidebar.classList.remove('hidden');
    if (chatHeader) chatHeader.style.display = 'none';
    if (typeof renderChatList === 'function') renderChatList();
  };
})();

/* ═══ push-notifications.js ═══ */
/* =============================================
   PUSH NOTIFICATIONS v1.1
   - Proactive chat notification permission prompt
   - Registers FCM token for BOTH calls AND messages
   - Handles permission state across all browsers
   - Respects user-disabled flag from notification-bell.js
   - iOS Safari: prompts to Add to Home Screen before enabling
   - Theme-aware prompt colors using CSS custom properties
   ============================================= */
(function () {
  'use strict';

  const PROMPTED_KEY     = 'tcPushPrompted';
  const DISABLED_KEY     = 'teamChatNotifUserDisabled';
  const REGISTERED_AT_KEY = 'tcPushRegisteredAt';
  const PROMPT_DELAY_MS  = 4000;
  const REREGISTER_MS    = 1000 * 60 * 60 * 24 * 5;

  function userDisabled() {
    try { return localStorage.getItem(DISABLED_KEY) === '1'; } catch (_) { return false; }
  }
  function alreadyPrompted() {
    try { return Boolean(localStorage.getItem(PROMPTED_KEY)); } catch (_) { return false; }
  }
  function setPrompted() {
    try { localStorage.setItem(PROMPTED_KEY, '1'); } catch (_) {}
  }
  function lastRegisteredAt() {
    try { return Number(localStorage.getItem(REGISTERED_AT_KEY) || 0); } catch (_) { return 0; }
  }
  function setRegisteredAt() {
    try { localStorage.setItem(REGISTERED_AT_KEY, String(Date.now())); } catch (_) {}
  }
  function shouldReregister() {
    return Date.now() - lastRegisteredAt() > REREGISTER_MS;
  }

  function notifSupported() {
    return 'Notification' in window && 'serviceWorker' in navigator;
  }
  function notifGranted() {
    return notifSupported() && Notification.permission === 'granted';
  }
  function notifBlocked() {
    return notifSupported() && Notification.permission === 'denied';
  }

  function isIOSSafari() {
    return /iPhone|iPad|iPod/i.test(navigator.userAgent) &&
      /^((?!chrome|android|crios|fxios|edg|opr|samsung).)*safari/i.test(navigator.userAgent);
  }
  function isStandalone() {
    return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  }

  async function registerToken(force) {
    if (typeof window.registerFcmTokenForCurrentUser === 'function') {
      try {
        await window.registerFcmTokenForCurrentUser({ force: Boolean(force) });
      } catch (e) {
        console.warn('[TC Push] registerFcmTokenForCurrentUser failed:', e);
      }
      return;
    }

    const user = window.currentUser;
    const db   = window.db;
    if (!user || !db || !window.firebase?.messaging) return;
    if (!window.FCM_VAPID_KEY) return;

    try {
      const messaging = firebase.messaging();
      const reg = await navigator.serviceWorker.ready;
      const token = await messaging.getToken({
        vapidKey: window.FCM_VAPID_KEY,
        serviceWorkerRegistration: reg
      });
      if (!token) return;

      const key = token.replace(/[^a-zA-Z0-9]/g, '').slice(-120);
      await db.collection('users').doc(user.uid).set({
        fcmTokens: {
          [key]: {
            token,
            platform: navigator.userAgent || 'web',
            updatedAt: firebase.firestore.FieldValue.serverTimestamp(),
            permission: Notification.permission,
            purpose: 'all'
          }
        },
        notificationsEnabled: true,
        lastFcmTokenUpdateAt: firebase.firestore.FieldValue.serverTimestamp()
      }, { merge: true });

      setRegisteredAt();
    } catch (e) {
      console.warn('[TC Push] Manual FCM registration failed:', e);
    }
  }

  function showPermissionPrompt() {
    if (document.getElementById('tcPushPromptBanner')) return;

    const banner = document.createElement('div');
    banner.id = 'tcPushPromptBanner';
    banner.setAttribute('role', 'dialog');
    banner.setAttribute('aria-label', 'Enable notifications');

    const isDark = document.documentElement.classList.contains('dark');
    const bg = isDark ? 'var(--surface-container)' : 'var(--surface-container-lowest, #fff)';
    const fg = isDark ? 'var(--on-surface)' : 'var(--on-surface)';
    const muted = 'var(--on-surface-variant)';
    const btnBg = 'var(--primary)';
    const btnFg = 'var(--on-primary)';

    banner.style.cssText = `
      position:fixed;bottom:70px;left:50%;transform:translateX(-50%);
      width:min(90vw,360px);background:${bg};color:${fg};
      border-radius:12px;padding:14px 16px;z-index:99990;
      box-shadow:0 6px 24px rgba(0,0,0,0.4);display:flex;
      flex-direction:column;gap:10px;font-family:inherit;
      animation:tcBannerIn 0.3s ease;
      border:1px solid var(--outline-variant);
    `;

    const style = document.createElement('style');
    style.textContent = `@keyframes tcBannerIn{from{opacity:0;transform:translateX(-50%) translateY(16px)}to{opacity:1;transform:translateX(-50%) translateY(0)}}`;
    document.head.appendChild(style);

    const iosHint = isIOSSafari() && !isStandalone()
      ? `<div style="font-size:11px;color:${muted};margin-top:4px;line-height:1.4;">
           iOS Safari: tap <b>Share → Add to Home Screen</b> first for full push support.
         </div>`
      : '';

    banner.innerHTML = `
      <div style="display:flex;align-items:flex-start;gap:12px;">
        <div style="font-size:22px;flex-shrink:0;margin-top:2px;">🔔</div>
        <div style="flex:1;min-width:0;">
          <div style="font-weight:700;font-size:14px;margin-bottom:3px;">Stay notified</div>
          <div style="font-size:12.5px;color:${muted};line-height:1.45;">
            Get alerts for new messages even when the app is closed or your screen is locked.
          </div>
          ${iosHint}
        </div>
        <button id="tcPushPromptClose" aria-label="Dismiss"
          style="background:none;border:none;color:${muted};font-size:18px;cursor:pointer;padding:0 2px;line-height:1;flex-shrink:0;">✕</button>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button id="tcPushPromptNo"
          style="background:none;border:none;color:${muted};font-size:13px;cursor:pointer;padding:6px 10px;border-radius:6px;">
          Not now
        </button>
        <button id="tcPushPromptYes"
          style="background:${btnBg};border:none;color:${btnFg};font-size:13px;font-weight:600;
                 cursor:pointer;padding:7px 16px;border-radius:8px;">
          Enable notifications
        </button>
      </div>
    `;

    document.body.appendChild(banner);

    function dismiss() {
      banner.remove();
      setPrompted();
    }

    document.getElementById('tcPushPromptClose').addEventListener('click', dismiss);
    document.getElementById('tcPushPromptNo').addEventListener('click', dismiss);
    document.getElementById('tcPushPromptYes').addEventListener('click', async function () {
      dismiss();
      try {
        const permission = await Notification.requestPermission();
        if (permission === 'granted') {
          await registerToken(true);
          if (typeof window.showToast === 'function') {
            window.showToast('Notifications enabled ✓');
          }
        }
      } catch (e) {
        console.warn('[TC Push] Permission request failed:', e);
      }
    });

    // Auto-dismiss after 15s
    setTimeout(dismiss, 15000);
  }

  /* ── Main init — runs after Firebase auth resolves ────────────────── */
  function initPush() {
    if (!notifSupported()) return;
    if (!window.firebase?.auth) {
      setTimeout(initPush, 600);
      return;
    }

    firebase.auth().onAuthStateChanged(async function (user) {
      if (!user) return;

      // If already granted: re-register silently if due
      if (notifGranted() && !userDisabled()) {
        if (shouldReregister()) {
          await registerToken(false);
        }
        return;
      }

      // If blocked: do nothing (user consciously denied)
      if (notifBlocked()) return;

      // If user disabled from bell toggle: do nothing
      if (userDisabled()) return;

      // If already prompted once: do nothing (don't nag)
      if (alreadyPrompted()) return;

      // Show the soft prompt after a short delay
      setTimeout(showPermissionPrompt, PROMPT_DELAY_MS);
    });
  }

  if (document.readyState === 'complete') {
    setTimeout(initPush, 0);
  } else {
    window.addEventListener('load', function () { setTimeout(initPush, 0); });
  }
})();

/* ═══ attachment-reliability.js ═══ */
/* =============================================
   ATTACHMENT RELIABILITY v1.0 — #26
   Upload retry (3× exponential backoff),
   download progress tracking, network recovery,
   file size validation.
   ============================================= */
(function () {
  'use strict';

  const MAX_RETRIES  = 3;
  const RETRY_BASE   = 1500;

  /* ─── Status badge in message bubble ───────────────────────── */
  function showBubbleStatus(localId, text, type) {
    if (!localId) return;
    const bubble = document.querySelector('[data-local-id="' + CSS.escape(String(localId)) + '"]');
    if (!bubble) return;
    let el = bubble.querySelector('.tc-attach-status');
    if (!el) {
      el = document.createElement('span');
      el.className = 'tc-attach-status';
      bubble.appendChild(el);
    }
    el.textContent = text;
    el.className = 'tc-attach-status tc-attach-status--' + (type || 'info');
    if (type === 'done') setTimeout(() => el.remove(), 2000);
  }

  /* ─── Retry wrapper ─────────────────────────────────────────── */
  async function withRetry(fn, localId, attempt) {
    attempt = attempt || 0;
    try { return await fn(); } catch (err) {
      if (attempt >= MAX_RETRIES) throw err;
      const delay = RETRY_BASE * Math.pow(2, attempt);
      showBubbleStatus(localId, 'Retrying (' + (attempt+1) + '/' + MAX_RETRIES + ')…', 'warn');
      await new Promise(r => setTimeout(r, delay));
      return withRetry(fn, localId, attempt + 1);
    }
  }

  /* ─── Patch upload functions ────────────────────────────────── */
  function patchUploaders() {
    ['uploadFile','uploadAttachment','uploadMedia','sendFileMessage'].forEach(name => {
      const orig = window[name];
      if (typeof orig !== 'function') return;
      window[name] = async function() {
        const localId = (arguments[arguments.length-1]||{}).localId || null;
        try {
          showBubbleStatus(localId, 'Uploading…', 'info');
          const result = await withRetry(() => orig.apply(this, arguments), localId);
          showBubbleStatus(localId, 'Sent ✓', 'done');
          return result;
        } catch (err) {
          showBubbleStatus(localId, 'Upload failed — tap to retry', 'error');
          throw err;
        }
      };
    });
  }

  /* ─── Network recovery: nudge error bubbles on reconnect ────── */
  function initNetworkRecovery() {
    let wasOffline = !navigator.onLine;
    window.addEventListener('online', () => {
      if (!wasOffline) return;
      wasOffline = false;
      document.querySelectorAll('.tc-attach-status--error').forEach(el => {
        el.textContent = 'Reconnected — please resend';
      });
    });
    window.addEventListener('offline', () => { wasOffline = true; });
  }

  /* ─── Download progress via XHR ────────────────────────────── */
  function initDownloadProgress() {
    document.addEventListener('click', e => {
      const link = e.target.closest('a.pdf-attachment-card, a.attachment-download, .tc-download-btn');
      if (!link || !link.href || !/^https?:\/\//.test(link.href)) return;
      e.preventDefault();
      const href = link.href;

      let prog = link.querySelector('.tc-dl-progress');
      if (!prog) {
        prog = document.createElement('div');
        prog.className = 'tc-dl-progress';
        prog.innerHTML = '<div class="tc-dl-bar"></div><span class="tc-dl-text">Downloading…</span>';
        link.appendChild(prog);
      }
      const bar  = prog.querySelector('.tc-dl-bar');
      const txt  = prog.querySelector('.tc-dl-text');

      const xhr = new XMLHttpRequest();
      xhr.open('GET', href, true);
      xhr.responseType = 'blob';
      xhr.onprogress = e => {
        if (e.lengthComputable) {
          const pct = Math.round((e.loaded/e.total)*100);
          if (bar) bar.style.width = pct + '%';
          if (txt) txt.textContent = 'Downloading… ' + pct + '%';
        }
      };
      xhr.onload = () => {
        prog.remove();
        const a = document.createElement('a');
        a.href = URL.createObjectURL(xhr.response);
        a.download = href.split('/').pop().split('?')[0] || 'download';
        a.style.display = 'none';
        document.body.appendChild(a);
        a.click();
        setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 2000);
        if (typeof showToast === 'function') showToast('File saved to Downloads', 'success');
      };
      xhr.onerror = () => {
        if (txt) txt.textContent = 'Download failed — tap to retry';
        if (bar) { bar.style.width = '100%'; bar.style.background = '#ef4444'; }
      };
      xhr.send();
    });
  }

  /* ─── File size validation ──────────────────────────────────── */
  function initFileValidation() {
    const MAX_BYTES = 100 * 1024 * 1024; // 100 MB
    document.addEventListener('change', e => {
      if (e.target.type !== 'file') return;
      const over = Array.from(e.target.files || []).filter(f => f.size > MAX_BYTES);
        if (over.length) {
        var msg = over.map(function(f){ return f.name; }).join(', ') + ' exceeds the 100 MB limit. Please choose a smaller file.';
        if (typeof showToast === 'function') showToast(msg, 'error');
        else console.warn('[AttachmentReliability] ' + msg);
        e.target.value = '';
      }
    });
  }

  function init() {
    patchUploaders();
    initNetworkRecovery();
    initDownloadProgress();
    initFileValidation();
  }

  if (document.readyState === 'complete') setTimeout(init, 0);
  else window.addEventListener('load', () => setTimeout(init, 0));
})();

/* ═══ app-init.js ═══ */
// ========================================
// APPLICATION INITIALIZATION
// ========================================

// M2: Sidebar expand/collapse toggle (tablet view)
window.toggleSidebarExpand = function() {
  var sidebar = document.getElementById('sidebar');
  var icon = document.getElementById('sidebar-toggle-icon');
  if (!sidebar) return;
  if (sidebar.classList.contains('w-20')) {
    sidebar.classList.remove('w-20');
    sidebar.classList.add('w-64');
    if (icon) icon.textContent = 'menu';
  } else {
    sidebar.classList.remove('w-64');
    sidebar.classList.add('w-20');
    if (icon) icon.textContent = 'menu_open';
  }
};

// Run framework initializes
init().catch((error) => {
  console.error("Application startup failed:", error);
  showStartupRecovery("Team Chat could not start. Please retry.");
});
